import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getUserSubscriptions, createSimpleSubscription } from '../services/simpleApi';
import { isAuthenticated } from '../util/auth';
import { useTheme } from '../context/ThemeContext';
import { useToast } from '../context/ToastContext';
import api from '../services/api';
import SimpleQRCode from '../components/SimpleQRCode';

const Subscriptions = () => {
  const { isDarkMode } = useTheme();
  const { success, error: showError } = useToast();
  const [subscriptions, setSubscriptions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [cancellingId, setCancellingId] = useState(null);
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [selectedSub, setSelectedSub] = useState(null);
  const [showPlansModal, setShowPlansModal] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [subscriptionModal, setSubscriptionModal] = useState(false);
  const [loadingSubscription, setLoadingSubscription] = useState(false);
  const [qrPlan, setQrPlan] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    if (!isAuthenticated()) {
      navigate('/login');
      return;
    }
    fetchSubscriptions();
  }, []);

  const fetchSubscriptions = async () => {
    try {
      setLoading(true);
      const res = await getUserSubscriptions();
      setSubscriptions(res.data);
    } catch (err) {
      setError('Failed to load subscriptions');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleCancelSubscription = async () => {
    if (!selectedSub) return;

    try {
      setCancellingId(selectedSub._id);
      await api.put(`/simple-subscription/${selectedSub._id}/cancel`);
      success('Subscription cancelled successfully');
      setShowCancelModal(false);
      setSelectedSub(null);
      fetchSubscriptions();
    } catch (err) {
      showError('Failed to cancel subscription');
      console.error(err);
    } finally {
      setCancellingId(null);
    }
  };

  const openCancelModal = (sub) => {
    setSelectedSub(sub);
    setShowCancelModal(true);
  };

  const getStatusStyles = (status) => {
    switch (status) {
      case 'active':
        return {
          bg: 'bg-gradient-to-r from-green-500/20 to-emerald-500/20',
          text: 'text-green-400',
          border: 'border-green-500/40',
          dot: 'bg-green-400'
        };
      case 'pending':
        return {
          bg: 'bg-gradient-to-r from-yellow-500/20 to-amber-500/20',
          text: 'text-yellow-400',
          border: 'border-yellow-500/40',
          dot: 'bg-yellow-400'
        };
      case 'cancelled':
        return {
          bg: 'bg-gradient-to-r from-red-500/20 to-rose-500/20',
          text: 'text-red-400',
          border: 'border-red-500/40',
          dot: 'bg-red-400'
        };
      default:
        return {
          bg: 'bg-gradient-to-r from-gray-500/20 to-slate-500/20',
          text: 'text-gray-400',
          border: 'border-gray-500/40',
          dot: 'bg-gray-400'
        };
    }
  };

  const getPaymentStatusStyles = (status) => {
    switch (status) {
      case 'paid':
        return { text: 'text-green-400', icon: '✓' };
      case 'pending':
        return { text: 'text-yellow-400', icon: '⏳' };
      default:
        return { text: 'text-gray-400', icon: '—' };
    }
  };

  const formatDate = (date) => {
    if (!date) return 'Not set';
    return new Date(date).toLocaleDateString('en-IN', {
      day: 'numeric',
      month: 'short',
      year: 'numeric'
    });
  };

  const getPlanDetails = (planType) => {
    const plans = {
      daily: {
        name: 'Daily Plan',
        price: 49,
        duration: 'day',
        description: 'Fresh milk every single day',
        features: [
          '500ml Milk Per Day',
          'Fresh Morning Delivery',
          'Standard Pricing',
          'No Commitment'
        ],
        color: 'from-blue-500 to-cyan-500',
        shadow: 'shadow-blue-500/25',
        border: 'border-blue-500/30',
        icon: 'M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z'
      },
      weekly: {
        name: 'Weekly Plan',
        price: 299,
        duration: 'week',
        description: '7 days of fresh dairy goodness',
        features: [
          '500ml Milk Per Day',
          'Flexible Delivery',
          '5% Discount Applied',
          'Priority Support'
        ],
        color: 'from-green-500 to-emerald-500',
        shadow: 'shadow-green-500/25',
        border: 'border-green-500/30',
        icon: 'M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z'
      },
      monthly: {
        name: 'Monthly Plan',
        price: 799,
        duration: 'month',
        description: 'Best value for regular families',
        features: [
          '15L Milk Per Month',
          'Custom Schedule',
          '20% Discount',
          'Free Delivery + Priority'
        ],
        color: 'from-purple-500 to-pink-500',
        shadow: 'shadow-purple-500/25',
        border: 'border-purple-500/30',
        icon: 'M13 10V3L4 14h7v7l9-11h-7z'
      }
    };
    return plans[planType] || plans.daily;
  };

  const handleSubscribe = async (planType) => {
    if (!isAuthenticated()) {
      navigate('/login');
      return;
    }
    setSelectedPlan(planType);
    setSubscriptionModal(true);
    setShowPlansModal(false);
  };

  const createSubscriptionHandler = async () => {
    if (!selectedPlan) return;
    try {
      setLoadingSubscription(true);
      const planDetails = getPlanDetails(selectedPlan);
      const subscriptionData = {
        planType: selectedPlan,
        planName: planDetails.name,
        price: planDetails.price
      };
      const response = await createSimpleSubscription(subscriptionData);
      if (response.status === 201 || response.status === 200) {
        success('Subscription created! Complete payment via QR code');
        setQrPlan(planDetails);
        setSubscriptionModal(false);
        fetchSubscriptions();
      }
    } catch (error) {
      showError(error.response?.data?.message || 'Failed to create subscription');
      console.error('Subscription error:', error);
    } finally {
      setLoadingSubscription(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center">
        <div className="text-center">
          <div className="relative w-16 h-16 mx-auto mb-4">
            <div className="absolute inset-0 rounded-full border-4 border-primary-500/20"></div>
            <div className="absolute inset-0 rounded-full border-4 border-primary-500 border-t-transparent animate-spin"></div>
          </div>
          <p className={`text-lg font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
            Loading subscriptions...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen py-8 px-4">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="mb-10">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <h1 className={`text-3xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
              My Subscriptions
            </h1>
          </div>
          <p className={`text-base ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
            View and manage your subscription plans
          </p>
        </div>

        {error && (
          <div className="mb-6 p-4 rounded-2xl bg-red-500/10 border border-red-500/30 text-red-400 font-medium">
            {error}
          </div>
        )}

        {subscriptions.length === 0 ? (
          <div className={`text-center py-20 rounded-3xl border-2 ${
            isDarkMode
              ? 'bg-gray-800/30 border-gray-700/50'
              : 'bg-white border-gray-200'
          }`}>
            <div className="w-20 h-20 mx-auto mb-6 rounded-2xl bg-gradient-to-br from-primary-500/20 to-secondary-500/20 flex items-center justify-center">
              <svg className="w-10 h-10 text-primary-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 5h10" />
              </svg>
            </div>
            <h3 className={`text-xl font-bold mb-3 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
              No subscriptions yet
            </h3>
            <p className={`text-base mb-8 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
              Choose a plan to get started with fresh milk delivery
            </p>
            <button
              onClick={() => setShowPlansModal(true)}
              className="inline-flex items-center gap-2 px-8 py-4 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-semibold hover:opacity-90 transition-all hover:scale-105"
            >
              <span>Browse Plans</span>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8l4 4m0 0l-4 4m4-4H3" />
              </svg>
            </button>
          </div>
        ) : (
          <div className="space-y-5">
            {subscriptions.map((sub) => {
              const statusStyles = getStatusStyles(sub.status);
              const paymentStyles = getPaymentStatusStyles(sub.paymentStatus);

              return (
                <div
                  key={sub._id}
                  className={`relative rounded-3xl border-2 overflow-hidden transition-all duration-300 hover:shadow-2xl ${
                    isDarkMode
                      ? 'bg-gray-800/50 border-gray-700/50 hover:border-gray-600/70'
                      : 'bg-white border-gray-200 hover:border-gray-300'
                  }`}
                >
                  {/* Status indicator bar */}
                  <div className={`h-1.5 ${statusStyles.bg}`}></div>

                  <div className="p-6">
                    <div className="flex flex-col lg:flex-row lg:items-center gap-6">
                      {/* Left section - Plan info */}
                      <div className="flex-1">
                        <div className="flex items-start gap-4 mb-4">
                          {/* Plan icon */}
                          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center flex-shrink-0 ${
                            isDarkMode ? 'bg-primary-500/20' : 'bg-primary-500/10'
                          }`}>
                            <span className="text-2xl">🥛</span>
                          </div>

                          <div className="flex-1">
                            <div className="flex items-center gap-3 mb-2">
                              <h3 className={`text-xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
                                {sub.planName || 'Subscription Plan'}
                              </h3>
                              <span className={`px-3 py-1 rounded-full text-xs font-semibold border ${statusStyles.bg} ${statusStyles.text} ${statusStyles.border} flex items-center gap-1.5`}>
                                <span className={`w-2 h-2 rounded-full ${statusStyles.dot}`}></span>
                                {sub.status?.charAt(0).toUpperCase() + sub.status?.slice(1)}
                              </span>
                            </div>
                            <p className={`text-sm font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                              ID: <span className="font-mono">{sub.subscriptionId || 'N/A'}</span>
                            </p>
                          </div>
                        </div>

                        {/* Details grid */}
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                          <div className={`p-3 rounded-xl ${isDarkMode ? 'bg-gray-700/30' : 'bg-gray-100'}`}>
                            <p className={`text-xs font-medium mb-1 ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>
                              Plan Type
                            </p>
                            <p className={`text-sm font-semibold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                              {sub.planType || 'N/A'}
                            </p>
                          </div>
                          <div className={`p-3 rounded-xl ${isDarkMode ? 'bg-gray-700/30' : 'bg-gray-100'}`}>
                            <p className={`text-xs font-medium mb-1 ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>
                              Duration
                            </p>
                            <p className={`text-sm font-semibold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                              {sub.duration || 'N/A'}
                            </p>
                          </div>
                          <div className={`p-3 rounded-xl ${isDarkMode ? 'bg-gray-700/30' : 'bg-gray-100'}`}>
                            <p className={`text-xs font-medium mb-1 ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>
                              Start Date
                            </p>
                            <p className={`text-sm font-semibold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                              {formatDate(sub.startDate)}
                            </p>
                          </div>
                          <div className={`p-3 rounded-xl ${isDarkMode ? 'bg-gray-700/30' : 'bg-gray-100'}`}>
                            <p className={`text-xs font-medium mb-1 ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>
                              End Date
                            </p>
                            <p className={`text-sm font-semibold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                              {formatDate(sub.endDate)}
                            </p>
                          </div>
                        </div>

                        {/* Payment status */}
                        <div className="mt-4 flex items-center gap-2">
                          <span className={`text-sm font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                            Payment:
                          </span>
                          <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-lg text-sm font-semibold ${
                            sub.paymentStatus === 'paid'
                              ? 'bg-green-500/10 text-green-400'
                              : 'bg-yellow-500/10 text-yellow-400'
                          }`}>
                            <span>{paymentStyles.icon}</span>
                            {sub.paymentStatus?.charAt(0).toUpperCase() + sub.paymentStatus?.slice(1)}
                          </span>
                        </div>
                      </div>

                      {/* Right section - Price and actions */}
                      <div className="flex flex-col items-end gap-4 lg:border-l-2 lg:pl-6 lg:min-w-[200px]">
                        <div className={`text-center lg:text-right w-full p-4 rounded-2xl ${
                          isDarkMode
                            ? 'bg-gradient-to-br from-primary-500/20 to-secondary-500/20 border border-primary-500/30'
                            : 'bg-gradient-to-br from-primary-50 to-secondary-50 border border-primary-200'
                        }`}>
                          <p className={`text-xs font-semibold uppercase tracking-wider mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                            Total Amount
                          </p>
                          <div className="flex items-baseline justify-center lg:justify-end gap-1">
                            <span className="text-2xl font-black bg-gradient-to-r from-primary-500 via-secondary-500 to-primary-500 bg-clip-text text-transparent">
                              ₹{sub.pricing?.totalAmount || sub.price || 0}
                            </span>
                          </div>
                          {sub.paymentStatus === 'paid' && (
                            <div className="mt-2 flex items-center justify-center lg:justify-end gap-1">
                              <svg className="w-4 h-4 text-green-500" fill="currentColor" viewBox="0 0 20 20">
                                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                              </svg>
                              <span className="text-xs font-semibold text-green-500">Paid</span>
                            </div>
                          )}
                        </div>

                        {/* Cancel button - only for active subscriptions */}
                        {sub.status === 'active' && (
                          <button
                            onClick={() => openCancelModal(sub)}
                            disabled={cancellingId === sub._id}
                            className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-semibold transition-all ${
                              isDarkMode
                                ? 'bg-red-500/10 text-red-400 hover:bg-red-500/20 border border-red-500/30'
                                : 'bg-red-50 text-red-500 hover:bg-red-100 border border-red-200'
                            }`}
                          >
                            {cancellingId === sub._id ? (
                              <>
                                <div className="w-4 h-4 border-2 border-red-400 border-t-transparent rounded-full animate-spin"></div>
                                <span>Cancelling...</span>
                              </>
                            ) : (
                              <>
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                                </svg>
                                <span>Cancel</span>
                              </>
                            )}
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Cancel Confirmation Modal */}
        {showCancelModal && selectedSub && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowCancelModal(false)}></div>
            <div className={`relative w-full max-w-md rounded-3xl p-6 ${
              isDarkMode ? 'bg-gray-800 border border-gray-700' : 'bg-white border border-gray-200'
            }`}>
              <div className="text-center">
                <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-red-500/20 flex items-center justify-center">
                  <svg className="w-8 h-8 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                </div>
                <h3 className={`text-xl font-bold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
                  Cancel Subscription?
                </h3>
                <p className={`text-sm mb-6 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                  Are you sure you want to cancel your <span className="font-semibold">{selectedSub.planName}</span> subscription? This action cannot be undone.
                </p>
                <div className="flex gap-3">
                  <button
                    onClick={() => setShowCancelModal(false)}
                    className={`flex-1 px-4 py-3 rounded-xl font-semibold ${
                      isDarkMode
                        ? 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                    }`}
                  >
                    Keep Plan
                  </button>
                  <button
                    onClick={handleCancelSubscription}
                    className="flex-1 px-4 py-3 rounded-xl font-semibold bg-red-500 text-white hover:bg-red-600"
                  >
                    Yes, Cancel
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Browse Plans Modal - Glass Effect */}
        {showPlansModal && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-md" onClick={() => setShowPlansModal(false)}></div>
            <div className={`relative w-full max-w-5xl max-h-[90vh] overflow-y-auto rounded-3xl p-6 md:p-8 ${
              isDarkMode ? 'bg-gray-900/80 border border-gray-700/50' : 'bg-white/80 border border-gray-200/50'
            } backdrop-blur-xl shadow-2xl`}>
              {/* Header */}
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h2 className={`text-2xl md:text-3xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
                    Choose Your Plan
                  </h2>
                  <p className={`mt-1 ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
                    Select the perfect milk delivery plan for your family
                  </p>
                </div>
                <button
                  onClick={() => setShowPlansModal(false)}
                  className={`p-2 rounded-xl transition-all ${
                    isDarkMode ? 'hover:bg-gray-700 text-gray-400' : 'hover:bg-gray-100 text-gray-500'
                  }`}
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>

              {/* Plans Grid */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {['daily', 'weekly', 'monthly'].map((planType) => {
                  const plan = getPlanDetails(planType);
                  return (
                    <div
                      key={planType}
                      className={`relative rounded-2xl border-2 overflow-hidden transition-all duration-300 hover:scale-[1.02] ${
                        isDarkMode
                          ? 'bg-gray-800/50 border-gray-700/50 hover:border-gray-600/70'
                          : 'bg-white/90 border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      {/* Plan Header */}
                      <div className={`p-6 bg-gradient-to-br ${plan.color} text-white`}>
                        <div className="flex items-center gap-3 mb-3">
                          <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={plan.icon} />
                            </svg>
                          </div>
                          <h3 className="text-xl font-bold">{plan.name}</h3>
                        </div>
                        <div className="flex items-baseline gap-1">
                          <span className="text-3xl font-black">₹{plan.price}</span>
                          <span className="text-white/80">/ {plan.duration}</span>
                        </div>
                        <p className="mt-2 text-sm text-white/90">{plan.description}</p>
                      </div>

                      {/* Features */}
                      <div className="p-6">
                        <ul className="space-y-3">
                          {plan.features.map((feature, idx) => (
                            <li key={idx} className="flex items-center gap-3">
                              <svg className="w-5 h-5 text-green-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                              </svg>
                              <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>{feature}</span>
                            </li>
                          ))}
                        </ul>

                        {/* CTA */}
                        <button
                          onClick={() => handleSubscribe(planType)}
                          className={`w-full mt-6 py-3 rounded-xl font-semibold text-white bg-gradient-to-r ${plan.color} hover:opacity-90 transition-all hover:scale-105 shadow-lg`}
                        >
                          Start {plan.name}
                        </button>
                      </div>

                      {/* Best Value Badge for Monthly */}
                      {planType === 'monthly' && (
                        <div className="absolute top-4 right-4 bg-gradient-to-r from-yellow-400 to-orange-500 text-white text-xs font-bold px-3 py-1 rounded-full">
                          BEST VALUE
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>

              {/* Footer Note */}
              <div className="mt-8 text-center">
                <p className={`text-sm ${isDarkMode ? 'text-gray-500' : 'text-gray-500'}`}>
                  All plans include: Pause/Resume anytime • No cancellation fees • 24/7 support
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Subscription Confirmation Modal */}
        {subscriptionModal && selectedPlan && (
          <div className="fixed inset-0 z-[101] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setSubscriptionModal(false)}></div>
            <div className={`relative w-full max-w-md rounded-3xl p-6 ${
              isDarkMode ? 'bg-gray-800 border border-gray-700' : 'bg-white border border-gray-200'
            }`}>
              {(() => {
                const planDetails = getPlanDetails(selectedPlan);
                return (
                  <div className="text-center">
                    <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-gradient-to-br from-primary-500/20 to-secondary-500/20 flex items-center justify-center">
                      <svg className="w-8 h-8 text-primary-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                      </svg>
                    </div>
                    <h3 className={`text-xl font-bold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
                      Confirm {planDetails.name}
                    </h3>
                    <p className={`text-sm mb-4 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                      You are about to subscribe to the {planDetails.name} at ₹{planDetails.price} per {planDetails.duration}.
                    </p>
                    <div className={`p-4 rounded-xl mb-6 ${isDarkMode ? 'bg-gray-700/50' : 'bg-gray-50'}`}>
                      <div className="flex justify-between items-center mb-2">
                        <span className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>Plan</span>
                        <span className={`font-semibold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>{planDetails.name}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>Price</span>
                        <span className={`font-semibold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>₹{planDetails.price} / {planDetails.duration}</span>
                      </div>
                    </div>
                    <div className="flex gap-3">
                      <button
                        onClick={() => setSubscriptionModal(false)}
                        className={`flex-1 px-4 py-3 rounded-xl font-semibold ${
                          isDarkMode
                            ? 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                        }`}
                      >
                        Cancel
                      </button>
                      <button
                        onClick={createSubscriptionHandler}
                        disabled={loadingSubscription}
                        className="flex-1 px-4 py-3 rounded-xl font-semibold bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        {loadingSubscription ? (
                          <div className="flex items-center justify-center gap-2">
                            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                            <span>Creating...</span>
                          </div>
                        ) : (
                          'Confirm'
                        )}
                      </button>
                    </div>
                  </div>
                );
              })()}
            </div>
          </div>
        )}

        {/* QR Code Modal */}
        {qrPlan && (
          <SimpleQRCode
            plan={qrPlan}
            onClose={() => setQrPlan(null)}
          />
        )}
      </div>
    </div>
  );
};

export default Subscriptions;
